#' Dynamic DiD for Treatments that Switch
#'
#' Dynamic effects of a binary treatment that can switch on and off, with 
#' placebo tests (de Chaisemartin and D'Haultfoeuille, 2024).
#'
#' @examples
#' \donttest{
#' # d is a data frame with one row per group and period
#' dcdh(data = d, dep = 'y', id = 'id', time = 'year', treat = 'D', effects = 3, placebo = 2)
#'}
#' @param data .
#' @param dep a string naming the outcome variable in \code{data}
#' @param id a string naming the group (unit) identifier variable in
#'   \code{data}
#' @param time a string naming the period variable in \code{data}; whole
#'   numbers, consecutive
#' @param treat a string naming the binary treatment variable in \code{data};
#'   it may switch on and off
#' @param effects number of dynamic effects to estimate (1 = the effect in the
#'   period of the first change)
#' @param placebo number of placebo estimates (pre-trend tests)
#' @param level confidence level in percent
#' @param plot \code{TRUE} (default) or \code{FALSE}, draw the effects and
#'   placebos
#' @param plotPalette \code{'color'} (default) or \code{'gray'}
#' @param showHelp \code{TRUE} or \code{FALSE} (default), show notes on the
#'   method
#' @param showGuide \code{TRUE} or \code{FALSE} (default), show a guide to the
#'   variables and the data format
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$info} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$tests} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$effects$asDF}
#'
#' \code{as.data.frame(results$effects)}
#'
#' @export
dcdh <- function(
    data,
    dep,
    id,
    time,
    treat,
    effects = 3,
    placebo = 2,
    level = 95,
    plot = TRUE,
    plotPalette = "color",
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("dcdh requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(id)) id <- jmvcore::resolveQuo(jmvcore::enquo(id))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(id), id, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(treat), treat, NULL))


    options <- dcdhOptions$new(
        dep = dep,
        id = id,
        time = time,
        treat = treat,
        effects = effects,
        placebo = placebo,
        level = level,
        plot = plot,
        plotPalette = plotPalette,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- dcdhClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

